-- Legacy DDL plus a synthetic-test marker; contains no production rows.
CREATE TABLE `db_buka_kasir` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `noref` varchar(50) NOT NULL,
  `id_kasir` int(11) NOT NULL,
  `saldo_awal` decimal(18,2) NOT NULL,
  `saldo_akhir` decimal(18,2) DEFAULT NULL,
  `tgl_buka` datetime NOT NULL,
  `tgl_tutup` datetime DEFAULT NULL,
  `user_id` int(11) NOT NULL,
  `status` int(11) NOT NULL,
  `saldo_kredit` decimal(18,2) NOT NULL,
  `company_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=COMPACT;

CREATE TABLE `db_cart` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sales_id` int(11) DEFAULT NULL,
  `sales_code` varchar(50) DEFAULT NULL,
  `customer_id` int(11) DEFAULT NULL,
  `nik_kar` varchar(50) DEFAULT NULL,
  `item_id` int(11) DEFAULT NULL,
  `barcode` varchar(100) DEFAULT NULL,
  `purchase_price` decimal(18,2) DEFAULT NULL,
  `price_per_unit` decimal(18,2) DEFAULT NULL,
  `sales_qty` int(11) DEFAULT NULL,
  `tax_id` int(11) DEFAULT NULL,
  `tax_amt` decimal(18,2) DEFAULT NULL,
  `tax_type` varchar(50) DEFAULT NULL,
  `discount_type` varchar(50) DEFAULT NULL,
  `discount_amt` decimal(18,2) DEFAULT NULL,
  `total_cost` decimal(18,2) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

CREATE TABLE `db_company` (
